with tb_t as (
select b.point_sq, a.raw_cnt from vi_m1_sv_meas_day a right join ( select b.* from vi_m1_sv_point_list b
and b.site_sq in ( select site_sq from fn_prj_sites(#{upSiteSq}::integer, #{lv}::integer) )
and b.site_sq = #{siteSq}::integer
) b on b.point_sq = a.point_sq
and a.meas_dt >= date_trunc('days', now()) - (#{day}::text || ' days')::interval and a.meas_dt < date_trunc('days', now())
), tb_total_t as ( select point_sq, count(*) cnt from tb_t where raw_cnt is not null group by point_sq ), tb_result_t as ( select a.point_sq, case when a.t_ratio - MOD(a.t_ratio::integer, 10) < 80 or t_ratio is null then 0 else a.t_ratio - MOD(a.t_ratio::integer, 10) end t_ratio from (
select point_sq, trunc((sum(raw_cnt)::float/(#{day}*24)::float)*100) t_ratio from tb_t where raw_cnt is not null group by point_sq
) a ), tb_total_d as ( select point_sq, count(*) cnt from tb_t group by point_sq ), tb_result_d as ( select point_sq, case when d_ratio < 80 or d_ratio is null then 0 else d_ratio end d_ratio from (
select a.point_sq, trunc(b.not_null_cnt::float / a.cnt::float) * 100 d_ratio from tb_total_d a left join ( select point_sq, count(*) not_null_cnt from tb_t where raw_cnt is not null group by point_sq ) b on b.point_sq = a.point_sq
) a ) select * from ( select d_ratio as ratio, count(*) cnt, '1'::text as type, 2::integer as indexOf from tb_result_d group by d_ratio union all select null as ratio, count(*), '0'::text as type, 2::integer as indexOf from tb_total_d a union all select t_ratio as ratio, count(*) cnt, '1'::text as type, 1::integer as indexOf from tb_result_t group by t_ratio union all select null as ratio, count(*), '0'::text as type, 1::integer as indexOf from tb_total_t ) a
a.indexOf = #{indexOf}

