with tb_target as (
select cast(extract( day from date_trunc('day', now()) - date_trunc('day', meas_dt)) as int) / 7 dw_no, a.* from fn_tb_meas_point_his_day_mov(#{pointSq}, to_date(#{begDate}, 'yyyy-mm-dd'), to_date(#{endDate}, 'yyyy-mm-dd') ) a
), tb_cnt as ( select count(*)/7 cnt, point_sq from tb_target group by point_sq ), tb_week as ( select a.* from tb_target a join tb_cnt b on b.point_sq = a.point_sq where
a.meas_dt > date_trunc('day', now()) - make_interval(days => (b.cnt::integer * 7)) and a.meas_dt <= date_trunc('day', now())
) select a.point_sq as "pointSq", a.meas_dt as "measDt", b.sum_term as"termCv" from (
select a.point_sq, a.dw_no, max(a.meas_dt) meas_dt from tb_week a group by a.point_sq, a.dw_no
) a join (
select a.point_sq, a.dw_no, sum(a.term_cv) sum_term from tb_week a group by a.point_sq, a.dw_no
) b on b.point_sq = a.point_sq and b.dw_no = a.dw_no order by a.meas_dt desc

select (ROW_NUMBER() OVER(order by a.ins_dt desc)) AS "rownum", a.data_sq as "dataSq", a.cust_name as "custNm", a.admin_no as "adminNo", a.addr as "addr", a.addr_new as "addrNew", a.loc_lng as "locLng", a.loc_lat as "locLat", a.business_name as "useType", a.master_site_sq as "masterSiteSq", a.master_site_nm as "masterSiteNm", a.site_nm as "siteNm", a.blk_nm as "blkNm", a.set_years as "setYears", a.cust_phone as "custPhoen", a.read_responsi as "readOpr", a.check_day as "checkDay", a.meter_no as "meterNo", a.pipe_diameter as "pipeDia", a.ami_type as "amiType", a.sub_dev_no as "subDevNo", a.dev_no as "devNo", a.company_nm as "companyNm", a.set_dt as "setDt", a.token_key as "tokenKey", a.ins_dt as "insDt", to_char(a.ins_dt, 'yyyy-mm-dd') as "insDtStr", a.flag as "flag", b.site_nm0 as "siteNm0" from tb_m1_info_import a left join vi_m1_sv_point_list b on b.admin_id = a.admin_no where a.use_cd = '1' and a.flag = '0'
and b.site_sq in ( select site_sq from fn_prj_sites(#{upSiteSq}::integer, #{lv}::integer) )
and b.site_sq = #{siteSq}::integer
and b.blk_sq in ( select blk_sq from fn_prj_blockes(#{upBlkSq}::integer, #{lv}::integer) )
and b.blk_sq = #{blkSq}::integer
and b.blk_sq IS NULL
and b.company_sq = #{comSq}::integer
and b.company_sq IS NULL
and b.ami_type = #{amiType}
and b.ami_type IS NULL
and b.read_opr = #{readOpr}
and b.read_opr IS NULL
and b.check_day = #{chkDay}
and b.check_day IS NULL
and b.use_type = #{useType}
and b.use_type IS NULL
and b.set_years = #{setYears}
and b.set_years IS NULL
and b.pipe_dia = #{pipeDia}::numeric
and b.pipe_dia is null
and b.use_cd in ('1', '9')
and position('1' in b.stat_cd) = #{statCd}::integer
and b.point_sq = #{pointSq}
AND b.send_cd = #{sendCd}
and b.cust_nm like '%' || #{cust_nm} || '%'
and b.admin_id like '%' || #{admin_no} || '%'
and b.tap_gb = #{tap_gb}
and b.bungu_cd = #{bungu_cd}
and b.site_sq in ( select site_sq from fn_prj_sites(#{addr_1} :: integer, '4' :: integer) )
and (b.addr_old like '%' || #{addr} || '%' or b.addr_new like '%' || #{addr} || '%')

