with tb_t as (
select position('1' in b.stat_cd) index_of, b.* from vi_m1_sv_point_list b
and b.site_sq in ( select site_sq from fn_prj_sites(#{upSiteSq}::integer, #{lv}::integer) )
and b.site_sq = #{siteSq}::integer
and b.blk_sq in ( select blk_sq from fn_prj_blockes(#{upBlkSq}::integer, #{lv}::integer) )
and b.blk_sq = #{blkSq}::integer
and b.blk_sq IS NULL
and b.company_sq = #{comSq}::integer
and b.company_sq IS NULL
and b.ami_type = #{amiType}
and b.ami_type IS NULL
and b.read_opr = #{readOpr}
and b.read_opr IS NULL
and b.check_day = #{chkDay}
and b.check_day IS NULL
and b.use_type = #{useType}
and b.use_type IS NULL
and b.set_years = #{setYears}
and b.set_years IS NULL
and b.pipe_dia = #{pipeDia}::numeric
and b.pipe_dia is null
and b.use_cd = '1'
and position('1' in b.stat_cd) = #{statCd}::integer
and b.point_sq = #{pointSq}
AND ( b.cust_nm like '%${searchParam}%' or b.admin_id like '%${searchParam}%' or b.addr_new like '%${searchParam}%'
)
), tb_all as ( select '200000000'::text stat_cd, count(*) cnt from tb_t ), tb_result as ( select stat_cd, count(*) cnt from (
select case when a.index_of in (0, 6, 7, 9, 10) then '000000000' else rpad( LPAD('1', a.index_of, '0'), 9, '0' ) end stat_cd from tb_t a
) a group by stat_cd union all select stat_cd, cnt from tb_all ) select stat_cd AS "statCd", cnt AS "cnt", case position('1' in stat_cd) when 1 then '통신 장애' when 2 then '계량기 장애' when 3 then 'Q4초과' when 4 then '역류' when 5 then '누수' when 8 then 'BAT' else case position('2' in stat_cd) when 1 then '전체' else '정상' end end "statCdStr" from tb_result

/*statCdSumarySimple*/ with tb_t as ( select position('1' in b.stat_cd) index_of, b.* from vi_m1_sv_point_list b where 1=1 and b.use_cd ='1'
and b.site_sq in ( select site_sq from fn_prj_sites(#{upSiteSq}::integer, 1::integer) )
and b.site_sq = #{siteSq}::integer
and b.blk_sq in ( select blk_sq from fn_prj_blockes(#{upBlkSq}::integer, #{lv}::integer) )
and b.blk_sq = #{blkSq}::integer
and b.blk_sq IS NULL
and b.company_sq = #{comSq}::integer
and b.company_sq IS NULL
and b.ami_type = #{amiType}
and b.ami_type IS NULL
and b.read_opr = #{readOpr}
and b.read_opr IS NULL
and b.check_day = #{chkDay}
and b.check_day IS NULL
and b.use_type = #{useType}
and b.use_type IS NULL
and b.set_years = #{setYears}
and b.set_years IS NULL
and b.pipe_dia = #{pipeDia}::numeric
and b.pipe_dia is null
), tb_all as ( select '200000000'::text stat_cd, index_of from tb_t ), tb_all_normal as ( select '300000000'::text as "stat_cd", index_of from tb_t where 1=1 ), tb_result as ( select stat_cd, count(*) cnt, statCdStr from ( select case when a.index_of = 1 then '100000000' when a.index_of = 2 then '010000000'
else '000000000' end stat_cd ,case when a.index_of = 1 then '통신장애' when a.index_of = 2 then '계량기장애'
else '정상' end statCdStr from tb_all_normal a where 1=1 ) a group by stat_cd, statCdStr union all select stat_cd, count(*) cnt, '전체' as "statCdStr" from tb_all group by stat_cd union all select stat_cd, count(*) cnt, '원격검침' as "statCdStr" from tb_all_normal group by stat_cd ) select stat_cd AS "statCd", cnt AS "cnt", statCdStr AS "statCdStr" from tb_result;

with tb_t as (
select * from vi_m1_sv_point_list where use_cd = '1'
and site_sq in ( select site_sq from fn_prj_sites(#{upSiteSq}::integer, #{lv}::integer) )
and site_sq = #{siteSq}::integer
) select key as "key", sq as "sq", val as "val" from ( select key, sq, val from (select 0 as key, set_years::character varying sq, set_years::character varying val from tb_t group by set_years order by set_years) a union all select key, sq, val from (select 1 as key, b.company_sq::character varying sq, b.company_nm::character varying val from tb_m1_cmap_device a join tb_m1_info_company b on a.company_sq = b.company_sq where 1=1 group by b.company_sq, b.company_nm order by b.company_nm ) a union all select key, sq, val from (select 2 as key, ami_type::character varying sq, ami_type::character varying val from tb_t group by ami_type order by ami_type) a union all select key, sq, val from (select 3 as key, pipe_dia::character varying sq, pipe_dia::character varying val from tb_t group by pipe_dia order by pipe_dia::numeric ) a union all select key, sq, val from (select 4 as key, use_type::character varying sq, use_type::character varying val from tb_t group by use_type order by use_type) a union all select key, sq, val from (select 5 as key, read_opr::character varying sq, read_opr::character varying val from tb_t group by read_opr order by read_opr) a union all select key, sq, val from (select 6 as key, blk_sq::character varying sq, blk_name::character varying val from tb_t group by blk_sq, blk_name order by blk_sq::numeric, blk_name) a union all select key, sq, val from (select 7 as key, check_day::character varying sq, check_day::character varying val from tb_t group by check_day order by check_day) a ) a
and a.key = #{key}

