select substr(p.admin_id,1,1) as "adminId1", --시군 substr(p.admin_id,3,16) as "adminId2", --수용가번호 to_char(end_meas_dt_t, 'yyyymmdd') as "endMeasDtT", --검침일자 trunc(end_accu_iv) as "endAccuIv", --당월지침 trunc(term_iv) as "termIv", --사용량 '' as "ijCd" --인정코드 from vi_m1_sv_point_list p left join fn_tb_meas_total_month_fromto(to_date(#{fromDt},'YYYY-MM-DD'), to_date(#{toDt},'YYYY-MM-DD')) measDay on measDay.point_sq = p.point_sq where p.use_cd = '1' and to_char(end_meas_dt_t, 'YYYY-MM-DD') = #{toDt}
and p.site_sq in ( select site_sq from fn_prj_sites(#{upSiteSq}::integer, #{lv}::integer) )
and p.site_sq = #{siteSq}::integer

select (ROW_NUMBER() OVER()) AS "rownum", p.admin_id as "adminId", '상수도' as "sudo", case when end_meas_dt_t is null then '장애' else '정상' end "accuCd", to_char(end_meas_dt_t, 'yyyymmdd') as "endMeasDtT", --검침일자 trunc(end_accu_iv) as "endAccuIv", --당월지침 trunc(term_iv) as "termIv" --사용량 from vi_m1_sv_point_list p left join fn_tb_meas_total_month_fromto(to_date(#{fromDt},'YYYY-MM-DD'), to_date(#{toDt},'YYYY-MM-DD')) measDay on measDay.point_sq = p.point_sq where p.use_cd = '1' and to_char(end_meas_dt_t, 'YYYY-MM-DD') = #{toDt}
and p.site_sq in ( select site_sq from fn_prj_sites(#{upSiteSq}::integer, #{lv}::integer) )
and p.site_sq = #{siteSq}::integer

